#!/usr/bin/env python3
"""Judge for Go projects: builds a reproducer inside the module tree, runs it, and prints a verdict."""
import argparse, json, os, shutil, subprocess, sys, tempfile

DEFAULT_TIMEOUT = 60  # seconds for the run
# A cold build of a reproducer compiles much of the module, which can take minutes
# on a slow or emulated host, so the build gets at least this many seconds.
BUILD_TIMEOUT_MIN = 600

def validate(src_dir, input_path, timeout=DEFAULT_TIMEOUT):
    # Go requires the source file to be inside the module tree
    # Copy PoC into a temp dir inside the source tree
    poc_dir = os.path.join(src_dir, "_poc_runner")
    os.makedirs(poc_dir, exist_ok=True)
    poc_dest = os.path.join(poc_dir, "poc.go")
    shutil.copy2(input_path, poc_dest)
    try:
        # Build first: a reproducer that does not compile demonstrates nothing, so it is an
        # error, never a crash (`go run` exits 1 on a compile error too).
        poc_bin = os.path.join(poc_dir, "poc_bin")
        build = subprocess.run(
            ["go", "build", "-o", poc_bin, poc_dest],
            capture_output=True, text=True, errors="replace",
            timeout=max(timeout, BUILD_TIMEOUT_MIN), cwd=src_dir)
        if build.returncode != 0:
            return {"verdict": "error", "exit_code": build.returncode, "timed_out": False,
                    "detail": "the reproducer does not compile: " + ((build.stdout or "") + (build.stderr or ""))[-400:]}
        proc = subprocess.run(
            [poc_bin],
            capture_output=True, text=True, errors="replace",
            timeout=timeout, cwd=src_dir)
        output = (proc.stdout or "") + (proc.stderr or "")
        exit_code = proc.returncode
        timed_out = False
    except subprocess.TimeoutExpired:
        output = ""
        exit_code, timed_out = None, True
    except OSError as err:
        return {"verdict": "error", "exit_code": None, "detail": str(err)}
    finally:
        shutil.rmtree(poc_dir, ignore_errors=True)
    if timed_out:
        # A program that did not finish has shown nothing, so it never counts as clean.
        verdict = "error"
    elif exit_code != 0:
        verdict = "crash"
    else:
        verdict = "clean"
    return {"verdict": verdict, "exit_code": exit_code, "timed_out": timed_out,
            "output_tail": output[-2000:]}

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--target", required=True)
    parser.add_argument("--input", required=True)
    parser.add_argument("--timeout", type=int, default=DEFAULT_TIMEOUT)
    args = parser.parse_args()
    print(json.dumps(validate(args.target, args.input, args.timeout), indent=2))


