def _decode(payload):
    return _b64.b64decode("".join(payload.split()))


def materialize(src_tgz, scripts_dir, config_dir):
    """Write the pristine snapshot and the environment files back out, each
    checked against its recorded sha256; any mismatch aborts the image build."""
    raw = _decode(PRISTINE_SRC_TGZ_B64)
    if _hashlib.sha256(raw).hexdigest() != PRISTINE_SRC_SHA256:
        raise SystemExit("embedded src.tgz failed its sha256 check")
    dest = _pathlib.Path(src_tgz)
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(raw)
    for kind, name, digest, payload in ENV_FILES:
        data = _decode(payload)
        if _hashlib.sha256(data).hexdigest() != digest:
            raise SystemExit("embedded %s/%s failed its sha256 check" % (kind, name))
        root = _pathlib.Path(scripts_dir if kind == "scripts" else config_dir)
        root.mkdir(parents=True, exist_ok=True)
        path = root / name
        path.write_bytes(data)
        path.chmod(0o755 if kind == "scripts" else 0o644)


def _materialize_main(argv):
    parser = argparse.ArgumentParser(prog="validate.py --materialize")
    parser.add_argument("--materialize", action="store_true", required=True)
    parser.add_argument("--src-tgz", required=True)
    parser.add_argument("--scripts-dir", required=True)
    parser.add_argument("--config-dir", required=True)
    args = parser.parse_args(argv)
    materialize(args.src_tgz, args.scripts_dir, args.config_dir)
# --- END embedded build assets ---


if __name__ == "__main__":
    if "--materialize" in sys.argv[1:]:
        _materialize_main(sys.argv[1:])
    else:
        main()
